/* ===================== YapNet single-file proxy =====================
   Wisp endpoint : WISP_URL   (Wisp v1 websocket, must end with /)
   Target site   : TARGET_URL
   Works as both: SVG document (top of file) and classic service worker.
   ------------------------------------------------------------------ */
if (!("ServiceWorkerGlobalScope" in globalThis)) {
	(async function () {
		const WISP_URL = "wss://kristenblackburnvolleyballcamps.com/socket/";
		const TARGET_URL = "https://89.116.170.52.sslip.io/";
		const SVGNS = "http://www.w3.org/2000/svg";
		const XH = "http://www.w3.org/1999/xhtml";
		const ICON = "data:image/png;base64,";

		const svg = document.documentElement;
		const fo = document.createElementNS(SVGNS, "foreignObject");
		fo.setAttribute("x", "0");
		fo.setAttribute("y", "0");
		fo.setAttribute("width", "100%");
		fo.setAttribute("height", "100%");
		const root = document.createElementNS(XH, "div");
		root.setAttribute(
			"style",
			"width:100%;height:100%;margin:0;display:flex;flex-direction:column;" +
				"background:#171717;color:#dbdee1;overflow:hidden;" +
				"font-family:'Segoe UI',system-ui,-apple-system,sans-serif;font-size:13px"
		);
		const bar = document.createElementNS(XH, "div");
		bar.setAttribute(
			"style",
			"display:flex;align-items:center;gap:10px;padding:7px 12px;" +
				"background:#1e1f22;border-bottom:1px solid #2b2d31;flex:0 0 auto"
		);
		const logo = document.createElementNS(XH, "span");
		logo.setAttribute(
			"style",
			'width:22px;height:22px;display:inline-block;flex:0 0 auto;' +
				'background:url("' +
				ICON +
				'") center/contain no-repeat'
		);
		const title = document.createElementNS(XH, "b");
		title.textContent = "YapNet";
		const status = document.createElementNS(XH, "span");
		status.setAttribute("style", "opacity:.65;overflow:hidden;text-overflow:ellipsis;white-space:nowrap");
		status.textContent = "Starting\u2026";
		const err = document.createElementNS(XH, "div");
		err.setAttribute(
			"style",
			"display:none;padding:12px 16px;background:#3b1d1f;color:#f2b8ba;" +
				"white-space:pre-wrap;overflow:auto;max-height:40%;flex:0 0 auto"
		);
		const view = document.createElementNS(XH, "iframe");
		view.setAttribute("style", "flex:1 1 auto;min-height:0;border:0;width:100%;background:#fff");
		view.setAttribute("title", "YapNet");
		bar.appendChild(logo);
		bar.appendChild(title);
		bar.appendChild(status);
		root.appendChild(bar);
		root.appendChild(err);
		root.appendChild(view);
		fo.appendChild(root);
		svg.appendChild(fo);
		window.__yapnetScriptHost = root;

		function setStatus(t) {
			status.textContent = t;
		}
		function fail(e) {
			console.error("[yapnet-svg]", e);
			setStatus("Error");
			let msg = String((e && e.message) || e);
			if (/MIME|javascript|SecurityError|register/i.test(msg)) {
				msg +=
					"\n\nThe service worker must be served with a JavaScript Content-Type." +
					" Configure the host to reply with Content-Type: application/javascript" +
					" when the request carries the header \"Service-Worker: script\"" +
					" (or Sec-Fetch-Dest: serviceworker), OR place the companion sw.js" +
					" file next to this SVG.";
			}
			err.style.display = "block";
			err.textContent = msg;
		}

		function withTimeout(p, ms, what) {
			return Promise.race([
				p,
				new Promise((_, rej) =>
					setTimeout(
						() =>
							rej(
								new Error(
									what +
										" timed out after " +
										Math.round(ms / 1000) +
										"s. Check that this host can reach cdn.jsdelivr.net."
								)
							),
						ms
					)
				),
			]);
		}

		function boot(p) {
			return new Promise((resolve, reject) => {
				const finish = (fn, v) => {
					navigator.serviceWorker.removeEventListener("message", onMsg);
					fn(v);
				};
				const onMsg = (ev) => {
					if (ev.data && ev.data.type === "init-bootstrap-error") {
						finish(reject, new Error("Service worker init failed: " + ev.data.message));
					}
				};
				navigator.serviceWorker.addEventListener("message", onMsg);
				p.then((v) => finish(resolve, v), (e) => finish(reject, e));
			});
		}

		try {
			if (!("serviceWorker" in navigator)) {
				throw new Error("Service workers are unavailable. Open this over https:// (or localhost).");
			}
			const base = location.pathname.replace(/[^/]*$/, "");
			const paths = {
				transport: "libcurl",
				wispPath: "/~unused-local-wisp-endpoint/",
				filePath: location.pathname + "?sw",
				swPath: location.pathname + "?sw",
				prefix: base + "~/sj/",
				scramjetBundlePath: base + "scram/scramjet.js",
				scramjetWasmPath: base + "scram/scramjet.wasm",
				scramjetUtilsBundlePath: base + "controller/controller.api.js",
				epoxyClientPath: base + "clients/epoxy-client.js",
				libcurlClientPath: base + "clients/libcurl-client.js",
				bareClientPath: base + "clients/bare-client.js",
				bootstrapApiPath: base + "bootstrap/api.js",
				bootstrapInitPath: base + "bootstrap/init.js",
				scramjetControllerApiPath: base + "controller/controller.api.js",
				scramjetControllerInjectPath: base + "controller/controller.inject.js",
				scramjetControllerSwPath: base + "controller/controller.sw.js",
				scramjetControllerVersionPin: "0.0.11",
				libcurlTransportVersionPin: "2.0.5",
				epoxyTransportVersionPin: "3.0.1",
			};

			setStatus("Installing worker\u2026");
			let controller;
			try {
				controller = await withTimeout(boot(initBootstrap(paths)), 120000, "Bootstrap install");
			} catch (e) {
				const msg = String((e && e.message) || e);
				if (!/MIME|javascript|SecurityError|register|Failed to load/i.test(msg)) throw e;
				console.warn("[yapnet-svg] self-registration failed, trying companion sw.js:", msg);
				setStatus("Retrying with sw.js\u2026");
				controller = await withTimeout(
					boot(initBootstrap(Object.assign({}, paths, { filePath: base + "sw.js" }))),
					120000,
					"Bootstrap install (sw.js)"
				);
			}

			const lc = window.LibcurlTransport;
			if (!lc || !lc.LibcurlClient) throw new Error("libcurl transport bundle failed to load");
			controller.setTransport(new lc.LibcurlClient({ wisp: WISP_URL }));

			setStatus("Preparing tunnel\u2026");
			await controller.wait();

			setStatus("Loading " + TARGET_URL.replace(/^https?:\/\//, "") + "\u2026");
			const frame = controller.createFrame(view);
			let loadedOnce = false;
			view.addEventListener("load", function () {
				loadedOnce = true;
				setStatus("Connected");
			});
			frame.go(TARGET_URL);
			setTimeout(function () {
				if (!loadedOnce) setStatus("Tunneling\u2026");
			}, 8000);
		} catch (e) {
			fail(e);
		}
	})();
}

/* Host this file at the ROOT of a site. Single-file hosting requires a
   response-header rule so the same URL answers service-worker fetches as
   JavaScript while normal opens stay image/svg+xml. Tested Caddy example:

   @sw { header Service-Worker script }
   @swdest { header Sec-Fetch-Dest serviceworker }
   @any { not path /never-exists }
   handle /yapnet.svg {
       header @sw >Content-Type "application/javascript; charset=utf-8"
       header @swdest >Content-Type "application/javascript; charset=utf-8"
       header @any {
           +Vary "Service-Worker, Sec-Fetch-Dest"
           defer
       }
       file_server
   }

   If your host cannot do that, drop the companion sw.js next to this file
   instead - the loader falls back to it automatically (sw.js must be the
   *patched* build output, same one that was inlined here).
*/
//
